using Microsoft.EntityFrameworkCore;
using ScanPlantAPI.Data;
using ScanPlantAPI.Models;

namespace ScanPlantAPI;

public class DeletePlantScript
{
    public static async Task Main(string[] args)
    {
        var optionsBuilder = new DbContextOptionsBuilder<ApplicationDbContext>();
        var connectionString = Environment.GetEnvironmentVariable("DATABASE_URL")
            ?? throw new InvalidOperationException("DATABASE_URL não configurada.");
        optionsBuilder.UseNpgsql(connectionString);

        using var context = new ApplicationDbContext(optionsBuilder.Options);

        // Buscar plantas com o nome científico ou comum contendo as palavras-chave
        var plants = await context.Plants
            .Where(p => 
                (p.ScientificName != null && p.ScientificName.Contains("Chlorophytum comosum")) ||
                (p.CommonName != null && (p.CommonName.Contains("Spingo") || p.CommonName.Contains("Espinho de Passarinho")))
            )
            .ToListAsync();

        if (!plants.Any())
        {
            Console.WriteLine("Nenhuma planta encontrada com esses critérios.");
            return;
        }

        Console.WriteLine($"Encontradas {plants.Count} planta(s):");
        foreach (var plant in plants)
        {
            Console.WriteLine($"  ID: {plant.Id}");
            Console.WriteLine($"  Nome Científico: {plant.ScientificName}");
            Console.WriteLine($"  Nome Comum: {plant.CommonName}");
            Console.WriteLine($"  Família: {plant.Family}");
            Console.WriteLine("  ---");
        }

        Console.WriteLine("\nDeseja excluir todas essas plantas? (S/N)");
        var confirm = Console.ReadLine();

        if (confirm?.ToUpper() == "S")
        {
            context.Plants.RemoveRange(plants);
            await context.SaveChangesAsync();
            Console.WriteLine($"\n{plants.Count} planta(s) excluída(s) com sucesso!");
        }
        else
        {
            Console.WriteLine("\nOperação cancelada.");
        }
    }
}

using System.Text;
using System.Security.Claims;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;
using Microsoft.IdentityModel.Tokens;
using System.Threading.RateLimiting;
using Microsoft.OpenApi.Models;
using ScanPlantAPI.Data;
using ScanPlantAPI.Models;
using ScanPlantAPI.Services;
using ScanPlantAPI.Services.ExternalProviders;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllers();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo
    {
        Title = "ScanPlant API",
        Version = "v1",
        Description = "API REST para o aplicativo ScanPlant - Identificação de plantas com IA",
        Contact = new OpenApiContact { Name = "ScanPlant Team", Email = "contato@scanplant.com" }
    });
    options.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
    {
        Description = "JWT Authorization header usando Bearer scheme.",
        Name = "Authorization",
        In = ParameterLocation.Header,
        Type = SecuritySchemeType.ApiKey,
        Scheme = "Bearer"
    });
    options.AddSecurityRequirement(new OpenApiSecurityRequirement
    {
        {
            new OpenApiSecurityScheme
            {
                Reference = new OpenApiReference { Type = ReferenceType.SecurityScheme, Id = "Bearer" }
            },
            Array.Empty<string>()
        }
    });
});

var connectionString = builder.Configuration.GetConnectionString("DefaultConnection");
if (string.IsNullOrWhiteSpace(connectionString))
{
    throw new InvalidOperationException("A variável ConnectionStrings__DefaultConnection é obrigatória.");
}

var phase0Enabled = builder.Configuration.GetValue<bool>("Phase0:Enabled");
if (phase0Enabled)
{
    Phase0DatabaseInitializer.ValidateConnectionTarget(connectionString);
}

var enableSensitiveDataLogging = builder.Configuration.GetValue<bool>("Diagnostics:EnableSensitiveDataLogging");
builder.Services.AddDbContext<ApplicationDbContext>(options =>
{
    options.UseNpgsql(connectionString);
    if (enableSensitiveDataLogging)
    {
        options.EnableSensitiveDataLogging();
        options.EnableDetailedErrors();
    }
});

builder.Services.AddIdentity<ApplicationUser, IdentityRole>(options =>
{
    options.Password.RequireDigit = true;
    options.Password.RequireLowercase = true;
    options.Password.RequireUppercase = false;
    options.Password.RequireNonAlphanumeric = false;
    options.Password.RequiredLength = 6;
    options.User.RequireUniqueEmail = true;
})
.AddEntityFrameworkStores<ApplicationDbContext>()
.AddDefaultTokenProviders();

var jwtKey = builder.Configuration["Jwt:Key"];
if (string.IsNullOrWhiteSpace(jwtKey))
{
    throw new InvalidOperationException("JWT Key not configured. Set JWT__KEY in the environment.");
}
var key = Encoding.ASCII.GetBytes(jwtKey);

builder.Services.AddAuthentication(options =>
{
    options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
})
.AddJwtBearer(options =>
{
    options.RequireHttpsMetadata = false;
    options.SaveToken = true;
    options.TokenValidationParameters = new TokenValidationParameters
    {
        ValidateIssuerSigningKey = true,
        IssuerSigningKey = new SymmetricSecurityKey(key),
        ValidateIssuer = true,
        ValidIssuer = builder.Configuration["Jwt:Issuer"],
        ValidateAudience = true,
        ValidAudience = builder.Configuration["Jwt:Audience"],
        ValidateLifetime = true,
        ClockSkew = TimeSpan.Zero
    };
});

builder.Services.AddCors(options =>
{
    options.AddDefaultPolicy(policy => policy.AllowAnyOrigin().AllowAnyMethod().AllowAnyHeader());
});
builder.Services.AddScoped<ITokenService, TokenService>();
builder.Services.AddSingleton<IValidateOptions<ExternalFallbackOptions>, ExternalFallbackOptionsValidator>();
builder.Services.AddOptions<ExternalFallbackOptions>()
    .BindConfiguration(ExternalFallbackOptions.SectionName)
    .ValidateOnStart();
builder.Services.AddSingleton<ExternalFallbackUploadValidator>();
builder.Services.AddHttpClient<IPlantIdentificationProvider, PlantNetIdentificationProvider>(ExternalProviderClientNames.PlantNet);
builder.Services.AddHttpClient<IPlantKnowledgeProvider, GroqPlantKnowledgeProvider>(ExternalProviderClientNames.Groq);
builder.Services.AddScoped<IExternalFallbackService, ExternalFallbackService>();

var externalFallbackOptions = builder.Configuration.GetSection(ExternalFallbackOptions.SectionName)
    .Get<ExternalFallbackOptions>() ?? new ExternalFallbackOptions();
builder.Services.AddRateLimiter(options =>
{
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    options.AddPolicy(ExternalFallbackRateLimitPolicy.Name, httpContext =>
    {
        var userId = httpContext.User.FindFirstValue(ClaimTypes.NameIdentifier);
        var partitionKey = string.IsNullOrWhiteSpace(userId) ? "unauthenticated" : userId;
        return RateLimitPartition.GetFixedWindowLimiter(partitionKey, _ => new FixedWindowRateLimiterOptions
        {
            PermitLimit = externalFallbackOptions.RateLimitPermitLimit,
            Window = TimeSpan.FromSeconds(externalFallbackOptions.RateLimitWindowSeconds),
            QueueLimit = 0,
            AutoReplenishment = true
        });
    });
});

var app = builder.Build();

if (phase0Enabled)
{
    try
    {
        await Phase0DatabaseInitializer.EnsureReadyAsync(app.Services, app.Lifetime.ApplicationStopping);
    }
    catch (Phase0DatabaseException exception)
    {
        app.Logger.LogError("A inicialização segura do banco isolado da Fase 0 falhou: {Reason}", exception.Message);
        throw;
    }
}

app.UseExceptionHandler(errorApp =>
{
    errorApp.Run(async context =>
    {
        context.Response.StatusCode = StatusCodes.Status500InternalServerError;
        context.Response.ContentType = "application/json";
        await context.Response.WriteAsJsonAsync(new { message = "Ocorreu um erro interno. Tente novamente mais tarde." });
    });
});

app.UseSwagger();
app.UseSwaggerUI(c =>
{
    c.SwaggerEndpoint("/swagger/v1/swagger.json", "ScanPlant API V1");
    c.RoutePrefix = "swagger";
    c.DocumentTitle = "ScanPlant API - Swagger";
});
app.UseCors();
app.UseAuthentication();
app.UseRateLimiter();
app.UseAuthorization();

app.MapGet("/health", () => Results.Ok(new
{
    status = "ok",
    environment = phase0Enabled ? "phase0" : "default"
}));
app.MapControllers();

app.Run();

